/**
 * Tier-2 specialized aggregations — `countIf`, `sumIf`, `stringAgg`,
 * `stringAggUnique`. These have argument shapes that don't fit the
 * generic aggregation pattern in `index.ts`:
 *
 *   - `countIf` / `sumIf` accept a *predicate text* second argument
 *     (e.g. `'>30'`, `'<30'`, `'30'`). The EDK models this as a
 *     structured `Predicate` object — `{ op, value }` — so the
 *     comparison operator is a typed literal union rather than a
 *     free-form string. The serializer assembles the wire predicate
 *     text.
 *
 *   - `stringAgg` accepts a variadic `ORDER BY` clause embedded inside its
 *     separator argument on the wire. The EDK models that as
 *     `{ orderBy: [{ field, direction }, ...] }`; direction defaults to ASC.
 */
import { coerce, emitStringLiteral, makeComposedExpr } from "./runtime.js";
// ---------------------------------------------------------------------------
// Predicate shape for countIf / sumIf
// ---------------------------------------------------------------------------
/** Discoverable comparison operators accepted by COUNTIF and SUMIF. */
export const predicateOp = {
    equal: "=",
    notEqual: "!=",
    notEqualSql: "<>",
    greaterThan: ">",
    greaterThanOrEqual: ">=",
    lessThan: "<",
    lessThanOrEqual: "<=",
};
function formatPredicate(p) {
    if (!("value" in p)) {
        const [name, value] = Object.entries(p)[0];
        const op = predicateOp[name];
        return emitStringLiteral(`${op === "=" ? "" : op}${String(value)}`);
    }
    const op = p.op === undefined || p.op === "=" ? "" : p.op;
    return emitStringLiteral(`${op}${String(p.value)}`);
}
// ---------------------------------------------------------------------------
// COUNTIF / SUMIF
// ---------------------------------------------------------------------------
/**
 * Count rows where `field` matches the predicate. Wire form:
 * `COUNTIF(field, 'predicate')` — the predicate is a quoted string
 * with the comparison operator prefix (e.g. `'>30'`) and value.
 */
export function countIf(field, predicate) {
    const f = coerce(field);
    return makeComposedExpr("number", [f], () => `COUNTIF(${f.toCalcString()}, ${formatPredicate(predicate)})`);
}
export function sumIf(field, predicate) {
    const f = coerce(field);
    return makeComposedExpr(f.__exprType, [f], () => `SUMIF(${f.toCalcString()}, ${formatPredicate(predicate)})`);
}
// ---------------------------------------------------------------------------
// STRING_AGG / STRING_AGG_UNIQUE
// ---------------------------------------------------------------------------
/** Discoverable sort directions for STRING_AGG's ORDER BY clause. */
export const orderByDirection = {
    ascending: "ASC",
    descending: "DESC",
};
function stringAggParts(field, separator, options) {
    const f = coerce(field);
    const s = coerce(separator);
    if (options === undefined) {
        return {
            dependencies: [f, s],
            render: () => `${f.toCalcString()}, ${s.toCalcString()}`,
        };
    }
    const orderBy = options.orderBy.map((item) => {
        const source = item.value ?? item.field;
        if (source === undefined)
            throw new Error("calc.stringAgg: orderBy requires `value`.");
        const expression = coerce(source);
        const direction = item.direction === "desc" ? "DESC" : item.direction === "asc" ? "ASC" : (item.direction ?? "ASC");
        return { expression, direction };
    });
    // Wire form: STRING_AGG(field, 'sep' ORDER BY field [ASC|DESC], …).
    return {
        dependencies: [f, s, ...orderBy.map(({ expression }) => expression)],
        render: () => `${f.toCalcString()}, ${s.toCalcString()} ORDER BY ${orderBy
            .map(({ expression, direction }) => `${expression.toCalcString()}${direction === "ASC" ? "" : ` ${direction}`}`)
            .join(", ")}`,
    };
}
/**
 * Concatenate `field` values across related rows, separated by
 * `separator`. Optional `orderBy` controls row ordering.
 */
export function stringAgg(field, separator, options) {
    const parts = stringAggParts(field, separator, options);
    return makeComposedExpr("text", parts.dependencies, () => `STRING_AGG(${parts.render()})`);
}
/** Distinct-only variant of `stringAgg`. Server emits duplicates once. */
export function stringAggUnique(field, separator) {
    const parts = stringAggParts(field, separator);
    return makeComposedExpr("text", parts.dependencies, () => `STRING_AGG_UNIQUE(${parts.render()})`);
}
